INSERT INTO public.cms_content_blocks VALUES ('ff971d7b-6d68-4f49-bab2-b7a0d91bd0a2', '5cbe999b-60b7-4dbb-90c0-062f84fe6c0e', 1, 'full-image', '{"src":"/figmaAssets/project-uae-china/gallery-full-1.png","alt":"Exhibition hall walkthrough","caption":"A larger-than-life display of towering scrolls told the story of the countries’ shared history and the beginnings of their relationship.","captionVisible":true}', '2026-08-16 18:51:00.625611');
INSERT INTO public.cms_content_blocks VALUES ('e5503e57-48f4-4339-a902-13214d638ac8', '5cbe999b-60b7-4dbb-90c0-062f84fe6c0e', 2, 'split-image', '{"wide":"right","left":{"src":"/figmaAssets/project-uae-china/gallery-2a.png","alt":"Exhibition detail — visitors exploring","caption":"","captionVisible":false,"mediaType":"image"},"right":{"src":"/figmaAssets/project-uae-china/gallery-2b.png","alt":"The Hall of Wisdom collaborative display","caption":"Visitors responded to the prompt, “How can our two countries contribute to a peaceful and prosperous future?” by choosing ribbons representing shared values and adding them to a glowing collective display—creating a living visualization of their hopes for the future.","captionVisible":true,"mediaType":"image"}}', '2026-08-16 18:51:00.625611');
INSERT INTO public.cms_content_blocks VALUES ('041ac404-f5bd-46b2-a1f4-02cd8a3c722a', '5cbe999b-60b7-4dbb-90c0-062f84fe6c0e', 3, 'split-image', '{"wide":"left","left":{"src":"/uploads/c4e02f46-1d8e-40a3-8747-db7c7b069fc4.mp4","alt":"Video recap of the event ","caption":"","captionVisible":false,"mediaType":"video"},"right":{"src":"/figmaAssets/project-uae-china/gallery-3b.png","alt":"Cultural exchange moment","caption":"Entrance to the Hall of Wisdom ","captionVisible":false,"mediaType":"image"}}', '2026-08-16 18:51:00.625611');
