INSERT INTO public.cms_content_blocks VALUES ('ddb62f76-3911-48b5-b4c8-9da97d654f6d', '0739b2b7-b59e-4732-b282-9bf17faf176b', 0, 'full-image', '{"src":"/uploads/86d4532f-4623-4a1d-814f-2ddb3a0316d8.png","alt":"","caption":"A gallery of real-world examples showed how creatives are already incorporating AI across their practice—from early brainstorming and prototyping to the final design output—expanding participants’ ideas of what collaboration with AI could look like.","captionVisible":true}', '2026-08-16 19:05:32.453779');
INSERT INTO public.cms_content_blocks VALUES ('c05f5143-c9f5-4881-90e7-f8a8c20493e2', '0739b2b7-b59e-4732-b282-9bf17faf176b', 1, 'full-image', '{"src":"/uploads/726bceaf-0a54-4d8f-9ff9-5d5ae70bc7ec.png","alt":"","caption":"AI identity stickers and analog polls created ongoing check-ins with the room, helping us understand where participants were in their AI journey and tailor the conversation to meet them where they were.","captionVisible":true}', '2026-08-16 19:05:32.453779');
