INSERT INTO public.cms_projects VALUES ('e20883b6-21b8-4ff5-bea2-5feb50fdb232', 'journey-to-net-zero', 'Cop 28: Journey to Net Zero', 'CASE STUDY', NULL, '/uploads/0869c35e-ad00-455b-a013-d20fb8d25c7a.png', 'Journey to Net Zero hero image placeholder', '{"client":"UAE Pavilion, COP28","year":"2023","scope":"Creative Direction, Experience Design, Exhibition Design, Content Strategy","role":"Creative Director"}', '["When our team joined the UAE’s Journey to Net Zero exhibition, the space was already in development—but its story wasn’t yet resonating with the leadership team. We quickly onboarded to the challenge of telling a national sustainability story that connected the UAE’s past, present, and future: from the resourcefulness and resilience of its ancestors to the innovators shaping its path toward net zero.","As Creative Director, I partnered with strategy to shape the narrative and carried it through to the final experience, translating the story into every layer of the exhibition. Working alongside interior architects and additional creative partners, I designed and creative directed the displays, films, archival storytelling, physical artifacts, and data visualizations that brought the narrative to life across the gallery, connecting ancestral practices with the innovations shaping the UAE’s net zero future. We extended the experience across both the public-facing Green Zone and the delegate-only Blue Zone, adapting the story, content, and visual language for two very different audiences while maintaining a cohesive journey from heritage to a net zero future."]', 'How might we connect the UAE’s deep-rooted culture of resourcefulness with its vision for a net zero future?', 'published', 2, true, 'Bringing the UAE’s vision for a net zero future to life at COP28.', 'designing-better-futures', '/figmaAssets/project-designing-better-futures/next-project.png', NULL, '2026-08-12 16:08:31.867152', '2026-08-16 21:07:41.482', NULL, '/uploads/dfffcff5-bb16-410c-8509-c76ceb547c23.png', NULL, '50.0% 58.9%', 1, 49.166668, 56.336807, 1.1524609, NULL);
INSERT INTO public.cms_projects VALUES ('e0cf4f97-742c-4a71-9b96-ab372a53a4f7', 'collective_intelligence_2', 'Collective Intelligence', 'CASE STUDY', NULL, '/uploads/0a247a34-5091-49fb-99e9-93aca23c63ea.png', NULL, '{"client":"The Knight Foundation ","year":"2026","scope":"Experience Strategy, Creative Direction, Experience Design, Visual Design, AI Experience Design","role":"Creative Director"}', '["When an organizational survey surfaced recurring challenges around collaboration, communication, meeting culture, and strategic alignment, we saw an opportunity to turn those insights into a shared experience. Rather than presenting the findings as another report, we designed a process that brought people together to reflect, collaborate, and build solutions around the challenges they were experiencing.","As Creative Director, I led the creative development of the experience, designing its visual language, physical materials, and collaborative moments from gallery through pitch. Employees first encountered their own stories and perspectives through an immersive gallery, then worked together in facilitated sessions to identify challenges, explore possibilities, and develop ideas through an analog, highly collaborative process. A custom AI tool helped teams synthesize their thinking into a clear presentation, creating a bridge from brainstorming to consensus and pitch preparation. Each team then presented a 60-second pitch to the group, with participants voting on the ideas they believed could have the greatest impact."]', 'How might we use AI to create more space for people to think, make, and solve problems together?', 'published', 3, true, 'Transforming employee insights into collective action through human-AI collaboration.', NULL, NULL, NULL, '2026-08-16 19:32:27.9645', '2026-08-16 21:08:06.563', 'confidential', '/uploads/3087dc80-6295-4d84-8770-3f538124671b.gif', NULL, '50.0% 50.0%', 1, 50, 50, 1, '$2b$12$3ciRoBRkUoGNOchq0ce6guemI3.1TgFvashbIp1t59LLyQljYPUBa');
INSERT INTO public.cms_projects VALUES ('7ea93fc4-2733-45b8-adb9-2b5f7f2e1b4d', 'expo-2020', 'Expo 2020: UAE Innovation Showcase', 'CASE STUDY', NULL, '/uploads/06749375-dfea-4b21-801d-7c073929f0f2.png', 'Expo 2020 hero image placeholder', '{"client":"UAE Pavilion, Expo 2020 Dubai","year":"2021","scope":"Creative Direction, Exhibition Design, Experience Design, Content Strategy","role":"Creative Lead"}', '["As Expo 2020 approached, our team joined the UAE Pavilion late in its development to help bring greater clarity and cohesion to the visitor experience. After the pavilion opened, an opportunity to create a new exhibition emerged: an Innovation Showcase highlighting the scientists, researchers, entrepreneurs, and makers shaping the UAE’s future. I stepped into the role of Creative Lead to develop the exhibition and translate their work into stories that could connect with a broad public audience.","Working directly with innovators across disciplines, I met with each innovator to understand not only what they had created, but why it mattered. I then led the creative development of bilingual exhibition stories, custom illustrations, physical displays, and visual representations that made complex research and technologies approachable without losing their substance. Rather than presenting innovation as a collection of technical achievements, the showcase centered the people and ideas behind them, inviting visitors to discover work they might never otherwise encounter."]', 'How might we bring the UAE’s most ambitious innovations to life in ways people could understand, explore, and connect to?', 'published', 6, true, 'Translating breakthrough ideas into an exhibition celebrating the UAE’s innovators at Expo 2020 Dubai.', 'collective-intelligence', '/figmaAssets/project-collective-intelligence/next-project.png', NULL, '2026-08-12 16:08:31.892787', '2026-08-16 21:08:32.301', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.cms_projects VALUES ('cf6b3b97-62e1-4f01-ad99-945d5ab3f05e', 'vibe-camp', 'Vibe Camp', 'CASE STUDY', NULL, '/uploads/6ded7bb3-82a6-455c-b5f6-0e34180af751.png', 'Vibe Camp hero image placeholder', '{"client":"SYPartners","year":"2026","scope":"Experience Strategy · Creative Direction · Experience Design · Visual Design · AI Design","role":"Creative Director"}', '["As AI tools rapidly become part of creative work, we designed Vibe Camp to help teams move beyond individual experimentation and discover how they could create together in entirely new ways. Inspired by the spirit of summer camp, we transformed a day of technical training into an immersive environment designed to make experimentation feel playful, approachable, and collaborative. The environment itself was designed to lower the stakes, creating permission to experiment before participants ever touched the technology.","The day moved from guided learning to independent exploration and then collaborative creation. Participants learned the fundamentals of vibe coding in Replit by building their own birdwatching applications before working in teams on a design challenge focused on creating deeper human connection at a large client event. Using shared FigJam workspaces and Replit’s collaborative workflows, teams designed, built, and presented working prototypes together—experiencing firsthand how AI could become part of a new creative process rather than simply another tool to learn."]', 'How might we give teams the confidence and space to discover a new way of creating together with AI?', 'published', 7, true, 'Helping teams build together in the era of AI collaboration.', 'building-bridges', '/figmaAssets/project-uae-china/hero.png', NULL, '2026-08-12 16:08:31.930365', '2026-08-16 16:55:36.226', NULL, '/uploads/b3b5f8a3-2f00-40b7-8bc0-9c309c3ec778.mp4', NULL, '50.0% 50.0%', 1, 52.5, 50, 1, NULL);
INSERT INTO public.cms_projects VALUES ('157801ab-53dc-4c59-aed2-f08f1786e312', 'radical-imagination', 'Radical Imagination', 'CASE STUDY', NULL, '/uploads/e6d24ff7-1e3a-4f45-a798-edca5aa73862.png', 'Radical Imagination hero image placeholder', '{"client":"SYPartners","year":"2026","scope":"Experience Strategy · Creative Direction · Experience Design · Visual Design","role":"Creative Director"}', '["As AI rapidly reshapes how organizations work, we designed Radical Imagination Studio to help leaders practice a fundamentally different way of thinking—challenging inherited assumptions and imagining entirely new possibilities. The experience became part of the broader conversation around AI and leadership, hosted for our partners internally, as an intimate gathering for select clients, and as a public-facing event during New York’s AI Week.","Participants moved through a carefully sequenced studio experience—exploring an exhibition of emerging AI possibilities, completing an AI-powered leadership diagnostic, contributing to live visualizations of collective perspectives, and working in teams to reimagine how AI could reshape a fictional client challenge. Each activity shifted participants from observing change to actively experimenting with it, creating a space where leaders could experience Radical Imagination rather than simply learn about it."]', 'How might we help leaders challenge the assumptions that shape how work gets done—and imagine what could come next?', 'published', 4, true, 'Designing an interactive studio to build radical imagination in the age of AI.', 'vibe-camp', '/figmaAssets/project-vibe-camp/next-project.png', NULL, '2026-08-12 16:08:31.917079', '2026-08-16 16:56:00.172', NULL, '/uploads/60d202ba-95ec-4593-b079-3ee7704d1ad4.png', NULL, '50.0% 48.5%', 1, 45.34722, 50, 1, NULL);
INSERT INTO public.cms_projects VALUES ('0739b2b7-b59e-4732-b282-9bf17faf176b', 'leading-through-design', 'Leading through Design', 'CASE STUDY', NULL, '/uploads/f2b68cc4-ced5-44d0-bf10-80c07d3822e9.jpg', 'Designing Better Futures hero image placeholder', '{"client":"Leaders of Design ","year":"2026","scope":"Experience Strategy, Creative Direction, Experience Design, Visual Design, AI Experience Design","role":"Creative Director"}', '["As AI rapidly reshapes the field, many creatives are grappling with uncertainty about what it means for their craft. For some Leaders of Design participants, this was their first opportunity to openly explore those questions with peers. We designed a work session that created space to acknowledge those concerns while inviting curiosity, experimentation, and a more collaborative relationship with AI.","Participants explored their personal relationship with AI, shared perspectives through analog polling, and mapped the design process to identify where they were willing to invite AI in—and where human judgment and expertise felt essential. An AI-powered Insight Synthesizer surfaced themes from the conversation in real time, while personalized microsites turned the session’s insights and commitments into individual takeaways. Rather than asking designers to give up control of their process, the experience invited them to consider what might become possible when they begin to evolve it."]', 'How might we help designers move through the fear of AI and become open to evolving their practice alongside it?', 'published', 5, true, 'Designing with AI — A collaborative work session helping design leaders explore where AI belongs in the creative process', 'expo-2020', '/figmaAssets/project-expo-2020/next-project.png', NULL, '2026-08-12 16:08:31.878713', '2026-08-16 19:05:32.453', 'confidential', '/uploads/6738478e-ddc0-4d63-887f-fd05da4ca2a1.jpg', NULL, '50.0% 55.4%', 1, 50, 55.46875, 1, '$2b$12$C88uFH.ck6E9eFNyl0uwLuV/yaVb7xuUhNo5rSlQSVwnEJejw7Rv.');
INSERT INTO public.cms_projects VALUES ('1a88f671-b42d-423a-8b02-c0bc5d224059', 'collective-intelligence', 'Collective Intelligence', 'CASE STUDY', NULL, '/uploads/0a247a34-5091-49fb-99e9-93aca23c63ea.png', 'Collective Intelligence hero image placeholder', '{"client":"The Knight Foundation","year":"2026","scope":"Experience Strategy, Creative Direction, Experience Design, Visual Design, AI Experience Design","role":"Creative Director"}', '["When an organizational survey surfaced recurring challenges around collaboration, communication, meeting culture, and strategic alignment, we saw an opportunity to turn those insights into a shared experience. Rather than presenting the findings as another report, we designed a process that brought people together to reflect, collaborate, and build solutions around the challenges they were experiencing.","As Creative Director, I led the creative development of the experience, designing its visual language, physical materials, and collaborative moments from gallery through pitch. Employees first encountered their own stories and perspectives through an immersive gallery, then worked together in facilitated sessions to identify challenges, explore possibilities, and develop ideas through an analog, highly collaborative process. A custom AI tool helped teams synthesize their thinking into a clear presentation, creating a bridge from brainstorming to consensus and pitch preparation. Each team then presented a 60-second pitch to the group, with participants voting on the ideas they believed could have the greatest impact."]', 'How might we use AI to create more space for people to think, make, and solve problems together?', 'draft', 3, false, 'Transforming employee insights into collective action through human-AI collaboration.', 'radical-imagination', '/figmaAssets/project-radical-imagination/next-project.png', '2026-08-16 19:50:53.373', '2026-08-12 16:08:31.907599', '2026-08-16 19:50:53.373', 'confidential', '/uploads/5e7b4fae-f5a1-426e-8fb1-8489c92fe015.gif', NULL, '50.0% 49.1%', 1, 49.791668, 51.041668, 1.1056724, '$2b$12$0wbEgUTUjNuXfbVsO/93xOFFmffLXnu.ZVOqie9lKvkGtkTPxRy2q');
INSERT INTO public.cms_projects VALUES ('5cbe999b-60b7-4dbb-90c0-062f84fe6c0e', 'building-bridges', 'Building Bridges for the Future', 'CASE STUDY', NULL, '/figmaAssets/project-uae-china/hero.png', 'Kristen Bend: UAE China immersive exhibition', '{"client":"Abu Dhabi National Projects Office","year":"2024","scope":"Experience Strategy, Creative Direction, Experience Design, Visual Design","role":"Creative Director"}', '["To celebrate forty years of partnership between the UAE and China, our team was invited into the project during its final stages to help bring clarity to an ambitious public exhibition already in development.","As Creative Director, I helped establish a cohesive narrative and visitor experience that connected history, culture, and participation into a single journey. We aligned multiple creative partners around a shared narrative that transformed diplomatic history into something visitors could experience, reflect on, and contribute to. Through immersive storytelling, contemporary cultural perspectives, and participatory installations, the exhibition invited thousands of visitors to discover the values connecting two nations—and add their own hopes for what the next chapter could become."]', 'How might we transform four decades of diplomacy into something people could experience, contribute to, and carry forward?', 'published', 1, true, 'Bringing forty years of UAE–China partnership to life through shared stories and public participation.', 'journey-to-net-zero', '/figmaAssets/project-journey-to-net-zero/next-project.png', NULL, '2026-08-12 16:08:31.634424', '2026-08-16 18:51:00.625', NULL, '/uploads/76a19f20-6cb0-479a-9aef-3cd05b53d465.png', NULL, '50.0% 58.8%', 1, 44.444443, 50, 1, NULL);
